    val n = reader.readLine().trim().toInt()
    val dp = Array(n) { LongArray(n) }

    for (length in 2 until n) {
        for (left in 0 until n - length) {
            val right = left + length
            var best = Long.MAX_VALUE

            for (middle in left + 1 until right) {
                val triangleWeight =
                    (left + 1).toLong() * (middle + 1).toLong() * (right + 1).toLong()
                val cost = dp[left][middle] + dp[middle][right] + triangleWeight
                if (cost < best) best = cost
            }

            dp[left][right] = best
        }
    }

    print(dp[0][n - 1])
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private class FastScanner {
    private val reader = BufferedReader(InputStreamReader(System.`in`))
    private var tokenizer = StringTokenizer("")

    fun nextInt(): Int {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = StringTokenizer(reader.readLine())
        }
        return tokenizer.nextToken().toInt()
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val dp = LongArray(n * n)

    for (length in 2 until n) {
        for (left in 0 until n - length) {
            val right = left + length
            var best = Long.MAX_VALUE

            for (middle in left + 1 until right) {
                val cost = dp[left * n + middle] +
                    dp[middle * n + right] +
                    (left + 1L) * (middle + 1L) * (right + 1L)

                if (cost < best) best = cost
            }

            dp[left * n + right] = best
        }
    }

    print(dp[n - 1])
}

